// Offline cache and auto-update for the browser (PWA) build. Not registered inside the Android app.
// VERSION and FILES are generated by scripts/build-sw.mjs; do not edit those two lines by hand.
const VERSION = '4f13f7f5a672';
const FILES = ["./","css/app.css","fonts/Vazirmatn.woff2","icons/apple-touch-icon.png","icons/icon-192.png","icons/icon-512.png","icons/icon.svg","icons/maskable-512.png","index.html","js/app.js","js/calendars.js","js/i18n.js","js/nav.js","js/pwa.js","js/schedule.js","js/store.js","js/theme.js","js/vendor/capacitor-core.js","js/vendor/jalaali.js","manifest.webmanifest"];
const CACHE = `ghest-${VERSION}`;

self.addEventListener('install', event => {
  // Fetch fresh copies (bypassing the HTTP cache) and take over as soon as they are stored.
  event.waitUntil(
    caches.open(CACHE)
      .then(cache => cache.addAll(FILES.map(f => new Request(f, { cache: 'reload' }))))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener('activate', event => {
  event.waitUntil(
    caches.keys()
      .then(keys => Promise.all(keys.filter(k => k.startsWith('ghest-') && k !== CACHE).map(k => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('fetch', event => {
  const req = event.request;
  if (req.method !== 'GET' || new URL(req.url).origin !== location.origin) return;
  event.respondWith(
    caches.match(req, { ignoreSearch: true })
      .then(hit => hit || (req.mode === 'navigate' ? caches.match('./') : fetch(req))),
  );
});
